<script lang="ts">
  import { onMount } from 'svelte'
  import { terminalRequest } from './api'
  type Minute = { minute:number;summary:{cpuPercent:{valid:number;sum:number};scope:string};rttP50Millis?:number }
  let {agent}: {agent:string}=$props()
  let minutes=$state<Minute[]>([]),hours=$state(1),error=$state(''),serverNow=$state(Date.now()),loading=$state(true)
  const recent=$derived(minutes.filter(item=>item.minute>=serverNow-hours*3600000))
  function points(field:'cpu'|'rtt') {
    return recent.map(item=>({time:item.minute,value:field==='cpu'?(item.summary.cpuPercent.valid?item.summary.cpuPercent.sum/item.summary.cpuPercent.valid:null):item.rttP50Millis??null}))
  }
  onMount(()=>{const abort=new AbortController();let busy=false;async function refresh(){if(busy)return;busy=true;try{const response=await terminalRequest(`/api/v2/machines/health?agent=${encodeURIComponent(agent)}`,{signal:abort.signal});const data=await response.json();if(!abort.signal.aborted){minutes=data.history||[];serverNow=data.serverNow;error=''}}catch(e){if(!abort.signal.aborted)error=e instanceof Error?e.message:'History unavailable'}finally{busy=false;loading=false}}void refresh();const timer=setInterval(()=>void refresh(),60000);return()=>{abort.abort();clearInterval(timer)}})
</script>
<details class="history"><summary>Connection & resource history</summary><div class="body"><label>Time range <select bind:value={hours}><option value={1}>Last hour</option><option value={6}>Last 6 hours</option><option value={24}>Last 24 hours</option></select></label><p>Each point is an observed minute. Gaps mean no valid sample. Past observations do not indicate a live connection.</p>{#if error}<p role="alert">{error}</p>{:else if loading}<p role="status">Loading observations…</p>{:else if !recent.length}<p>No retained observations in this time range yet.</p>{:else}{#each ['cpu','rtt'] as field}{@const values=points(field as 'cpu'|'rtt')}{@const max=field==='cpu'?100:Math.max(1,...values.map(item=>item.value??0))}<figure><figcaption>{field==='cpu'?'CPU · mean utilisation (%)':'Private host RTT · median (ms)'} · {field==='cpu'?'0–100':`0–${Math.ceil(max)}`}</figcaption><svg viewBox="0 0 600 110" role="img" aria-label={field==='cpu'?'Observed CPU minute means':'Observed RTT minute medians'}><path d="M 0 100 H 600" stroke="var(--line)" />{#each values as point}{#if point.value!==null}<circle cx={Math.max(2,Math.min(598,600*(point.time-(serverNow-hours*3600000))/(hours*3600000)))} cy={100-90*point.value/max} r="2.5" fill="var(--accent)"><title>{new Date(point.time).toLocaleString()}: {point.value.toFixed(1)} {field==='cpu'?'%':'ms'}</title></circle>{/if}{/each}</svg><details><summary>Read observations as a table</summary><div class="table"><table><thead><tr><th>Minute</th><th>{field==='cpu'?'Mean CPU (%)':'Median RTT (ms)'}</th></tr></thead><tbody>{#each values as point}<tr><td>{new Date(point.time).toLocaleString()}</td><td>{point.value===null?'No valid sample':point.value.toFixed(1)}</td></tr>{/each}</tbody></table></div></details></figure>{/each}{/if}</div></details>
<style>.history{border:1px solid var(--line);border-radius:10px;background:var(--card);font-size:.78rem}.history>summary{padding:12px 16px;cursor:pointer}.body{padding:0 16px 16px}.body>p{color:var(--muted);line-height:1.5}label{display:flex;gap:12px;align-items:center}select{font-size:.8rem}figure{margin:20px 0 0}figcaption{font-weight:600}svg{width:100%;max-height:160px;display:block}.table{max-height:240px;overflow:auto}table{width:100%;font-size:.75rem;text-align:left}th,td{padding:6px;border-bottom:1px solid var(--line)}</style>
